def read(path:Path)->str:return path.read_text(encoding='utf-8')
def write(path:Path,text:str)->None:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text,encoding='utf-8')

def jsonld_scripts(text:str):
    for raw in re.findall(r'<script type="application/ld\+json">(.*?)</script>',text,re.S):
        try:yield json.loads(raw)
        except json.JSONDecodeError:continue

def update_meta_and_article(text:str,slug:str)->str:
    description=DESCRIPTIONS[slug]
    text=re.sub(r'<meta name="description" content="[^"]+">',f'<meta name="description" content="{html.escape(description,quote=True)}">',text,count=1)
    text=re.sub(r'<meta property="og:description" content="[^"]+">',f'<meta property="og:description" content="{html.escape(description,quote=True)}">',text,count=1)
    text=re.sub(r'<meta name="twitter:description" content="[^"]+">',f'<meta name="twitter:description" content="{html.escape(description,quote=True)}">',text,count=1)
    pattern=re.compile(r'(<script type="application/ld\+json">)(.*?)(</script>)',re.S)
    def replace(m):
        try:data=json.loads(m.group(2))
        except json.JSONDecodeError:return m.group(0)
        if data.get('@type') in {'Article','WebPage'}:
            data['description']=description
        if data.get('@type')=='Article':data['dateModified']=TODAY
        return m.group(1)+json.dumps(data,ensure_ascii=False,separators=(',',':'))+m.group(3)
    return pattern.sub(replace,text)

def enhance_article(slug:str)->None:
    path=ROOT/'posts'/f'{slug}.html';text=read(path)
    for old,new in FIXES.get(slug,[]):text=text.replace(old,new)
    text=re.sub(r'<!-- SEO-PHASE1-START -->.*?<!-- SEO-PHASE1-END -->\s*','',text,flags=re.S)
    marker='<div class="art-body">'
    text=text.replace(marker,marker+ENHANCEMENTS[slug],1)
    text=update_meta_and_article(text,slug)
    text=re.sub(r'<!-- CLUSTER-LINKS-START -->.*?<!-- CLUSTER-LINKS-END -->\s*','',text,flags=re.S)
    titles={item['s']:item['t'] for item in json.loads(read(ROOT/'search-index.json'))}
    cluster='<!-- CLUSTER-LINKS-START --><section class="cluster-links" aria-labelledby="cluster-links-title"><h2 id="cluster-links-title">أكمل القراءة في هذا الموضوع</h2><ul>'+''.join(f'<li><a href="../posts/{target}.html">{titles[target]}</a></li>' for target in CLUSTER_LINKS[slug])+'</ul></section><!-- CLUSTER-LINKS-END -->\n'
    insert_at=text.find('<section class="sources"')
    if insert_at<0:insert_at=text.find('<div class="share">')
    text=text[:insert_at]+cluster+text[insert_at:]
    # أعد بناء الفهرس المرئي من عناوين H2 ذات المعرفات.
    start=text.index('<div class="art-body">');end=text.find('<!-- CLUSTER-LINKS-START -->',start)
    if end<0:end=text.find('<section class="sources"',start)
    if end<0:end=text.find('<div class="share">',start)
    body=text[start:end]
    headings=re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body,re.S)
    items=''.join(f'<li><a href="#{anchor}">{re.sub(r"<.*?>","",title)}</a></li>' for anchor,title in headings)
    if items:
        toc=f'<nav class="toc" aria-label="جدول محتويات المقال"><b>محتويات المقال</b><ul>{items}</ul></nav>'
        text=re.sub(r'<nav class="toc" aria-label="جدول محتويات المقال">.*?</nav>',toc,text,count=1,flags=re.S)
    write(path,text)

def add_recipe_schema(slug:str,data:dict)->None:
    path=ROOT/'posts'/f'{slug}.html';text=read(path)
    article=next(x for x in jsonld_scripts(text) if x.get('@type')=='Article')
    recipe={
      '@context':'https://schema.org','@type':'Recipe','@id':f'{BASE}/posts/{slug}.html#recipe',
      'name':data['name'],'description':data['description'],'image':[article['image']],
      'author':{'@type':'Organization','name':'فريق تحرير دليلك','url':AUTHOR_URL},
      'datePublished':article['datePublished'],'dateModified':TODAY,
      'prepTime':data['prepTime'],'cookTime':data['cookTime'],'totalTime':data['totalTime'],
      'recipeYield':data['recipeYield'],'recipeCuisine':data['recipeCuisine'],'recipeCategory':data['recipeCategory'],
      'recipeIngredient':data['ingredients'],
      'recipeInstructions':[{'@type':'HowToStep','position':i+1,'text':step} for i,step in enumerate(data['steps'])],
      'mainEntityOfPage':f'{BASE}/posts/{slug}.html'
    }
    text=re.sub(r'<script type="application/ld\+json">\s*\{[^<]*"@type":"Recipe".*?</script>\s*','',text,flags=re.S)
    insertion='<script type="application/ld+json">'+json.dumps(recipe,ensure_ascii=False,separators=(',',':'))+'</script>\n'
    text=text.replace('</main>',insertion+'</main>',1)
    write(path,text)

def set_noindex()->None:
    for name in ('search.html','thanks.html','404.html'):
        path=ROOT/name;text=read(path)
        text=re.sub(r'<meta name="robots" content="[^"]+">','<meta name="robots" content="noindex, follow">',text,count=1)
        write(path,text)

